def test_the_text_formats_read_the_input_name_for_the_manifest_alone(tmp_path, capsys):
    """``run`` reads the input records for the vcf and json formats and for a structural-variant
    class alone: a default or tab comparison beside ``--manifest`` names ``--input`` for the flag
    set documented over that input, opens none of its lines (the file need not exist), and
    leaves out the runs documented over another input."""
    reference = default_text(default_row("rs1", "21:100", "A", "ENST1", "intron_variant", "IMPACT=MODIFIER"))
    (tmp_path / "ref.txt").write_text(reference, encoding="utf-8")
    (tmp_path / "cand.txt").write_text(reference.replace("intron_variant", "missense_variant"), encoding="utf-8")
    item = {"location": "21:100", "allele": "A", "feature": "ENST1", "vep_rs_consequence_sets": ["missense_variant"], "expected_divergence": "some_class"}
    manifest = tmp_path / "manifest.json"
    manifest.write_text(json.dumps({
        "divergences": [],
        "flag_sets": [
            {"name": "documented", "input": "documented.vcf", "divergences": [item]},
            {"name": "other", "input": "other.vcf", "divergences": []},
        ],
    }), encoding="utf-8")
    report = tmp_path / "report.json"
    argv = ["--expected", str(tmp_path / "ref.txt"), "--actual", str(tmp_path / "cand.txt"), "--manifest", str(manifest), "--report", str(report)]
    for fmt in ("default", "tab"):
        assert cvf.main(["--format", fmt, *argv, "--masks", "some_class", "--input", str(tmp_path / "documented.vcf")]) == 0
        assert json.loads(report.read_text(encoding="utf-8"))["masks"]["applied"] == {"some_class": 1}
        assert cvf.main(["--format", fmt, *argv, "--masks", "some_class", "--input", str(tmp_path / "other.vcf")]) == 1
        assert json.loads(report.read_text(encoding="utf-8"))["masks"]["applied"] == {}
    capsys.readouterr()
    for reading in (["--format", "vcf"], ["--format", "default", "--masks", "reference_skipped_record"]):
        assert cvf.main([*reading, *argv, "--input", str(tmp_path / "documented.vcf")]) == 2
        assert capsys.readouterr().err.startswith(f"ERROR: [compare_vep_formats] cannot read {tmp_path / 'documented.vcf'}: ")


# The fabricated rows of the manifest-reading tests below: record ``i`` is one deletion on one
# transcript, written in every format the manifest's reader serves with the consequence set
# its side gives it. Ensembl VEP's side writes ``KEPT_SET``; the candidate writes ``LOST_SET``
# in a run without a reference sequence.
KEPT_SET, LOST_SET = "3_prime_UTR_variant,stop_retained_variant", "3_prime_UTR_variant,stop_lost"
OTHER_SET = "3_prime_UTR_variant,coding_sequence_variant"
SET_IMPACT = {KEPT_SET: "LOW", LOST_SET: "HIGH", OTHER_SET: "MODIFIER"}
MANIFEST_FORMATS = ("default", "tab", "vcf", "json", "parquet")
WITH_REFERENCE = "vep_rs_consequence_sets_with_reference_sequence"
REMOVED_CLASS = cvf.STOP_CODON_REMOVED_WITHOUT_STOP_CODON_TEST


def fabricated_record(ordinal: int) -> tuple[str, str, str]:
    """The VCF line, the Location and the transcript of the fabricated record ``ordinal``."""
    position = 100 * (ordinal + 1)
    return f"21\t{position - 1}\tdel{ordinal}\tCAT\tC\t.\t.\t.", f"21:{position}-{position + 1}", f"ENST{ordinal + 1}"


def fabricated_ensembl_line(ordinal: int, separator: str = "\t") -> str:
    """The fabricated record ``ordinal`` as a line of the Ensembl default input format."""
    position = 100 * (ordinal + 1)
    return separator.join(["21", str(position), str(position + 1), "AT/-", "+"])


def fabricated_item(ordinal: int, klass: str, sets: tuple[str, ...] = (LOST_SET,), **keys) -> dict:
    """The ``divergences`` item of the fabricated record ``ordinal`` under the class ``klass``."""
    _, location, feature = fabricated_record(ordinal)
    return {
        "location": location, "allele": "-", "feature": feature, "feature_type": "Transcript", "record_indices": [ordinal],
        "vep_consequence_set": KEPT_SET, "vep_rs_consequence_sets": list(sets), "expected_divergence": klass, **keys,
    }


def fabricated_output(fmt: str, sets: list[str], echoed: list[str] | None = None) -> str:
    """One row per fabricated record in the format ``fmt``, record ``i`` carrying the set
    ``sets[i]``; ``echoed`` is the input line each JSON object echoes where it is not the
    record's VCF line."""
    records = [fabricated_record(i) for i in range(len(sets))]
    if fmt == "default":
        return default_text(*(
            default_row(f"del{i}", location, "-", feature, terms, f"IMPACT={SET_IMPACT[terms]}")
            for i, ((_, location, feature), terms) in enumerate(zip(records, sets))
        ))
    if fmt == "tab":
        header = "#Uploaded_variation\tLocation\tAllele\tGene\tFeature\tFeature_type\tConsequence\tIMPACT"
        rows = [
            f"del{i}\t{location}\t-\tENSG1\t{feature}\tTranscript\t{terms}\t{SET_IMPACT[terms]}"
            for i, ((_, location, feature), terms) in enumerate(zip(records, sets))
        ]
        return "\n".join([header, *rows]) + "\n"
    if fmt == "vcf":
        header = ('##INFO=<ID=CSQ,Number=.,Type=String,Description="Consequence annotations from Ensembl VEP. '
                  'Format: Allele|Consequence|IMPACT|Feature_type|Feature">')
        lines = [
            f"{line[:-1]}CSQ=-|{terms.replace(',', '&')}|{SET_IMPACT[terms]}|Transcript|{feature}"
            for (line, _, feature), terms in zip(records, sets)
        ]
        return "\n".join([header, *lines]) + "\n"
    assert fmt == "json", fmt
    return "".join(
        json.dumps({
            "input": line if echoed is None else echoed[i], "id": f"del{i}", "allele_string": "AT/-",
            "most_severe_consequence": terms.split(",")[0],
            "transcript_consequences": [
                {"variant_allele": "-", "transcript_id": feature, "consequence_terms": terms.split(","), "impact": SET_IMPACT[terms]},
            ],
        }) + "\n"
        for i, ((line, _, feature), terms) in enumerate(zip(records, sets))
    )


def compare_fabricated(tmp_path: Path, fmt: str, expected: list[str], actual: list[str], manifest: dict | None, *options: str,
                       input_lines: list[str] | None = None, echoed: list[str] | None = None,
                       input_name: str = "variants.vcf") -> tuple[int, dict]:
    """The comparator's exit status and report on the fabricated pair in the format ``fmt``:
    Ensembl VEP's side carrying the sets ``expected`` and the candidate's ``actual``, read
    beside ``manifest`` under ``options``. ``input_lines`` is the input where it is not the
    records' VCF lines, ``echoed`` what the JSON objects then echo of it, and ``input_name``
    the input's file name. A Parquet pair is the tab text against the candidate's rows written
    as Parquet."""
    tmp_path.mkdir(exist_ok=True)
    text_format = "tab" if fmt == "parquet" else fmt
    reference, candidate, report = tmp_path / "vep.out", tmp_path / "candidate.out", tmp_path / "report.json"
    reference.write_text(fabricated_output(text_format, expected, echoed), encoding="utf-8")
    candidate_text = fabricated_output(text_format, actual, echoed)
    if fmt == "parquet":
        candidate = tmp_path / "candidate.parquet"
        write_parquet(candidate, candidate_text, data_lines(candidate_text))
    else:
        candidate.write_text(candidate_text, encoding="utf-8")
    lines = input_lines if input_lines is not None else [fabricated_record(i)[0] for i in range(len(expected))]
    (tmp_path / input_name).write_text("".join(f"{line}\n" for line in lines), encoding="utf-8")
    argv = ["--format", fmt, "--expected", str(reference), "--actual", str(candidate), "--report", str(report),
            "--input", str(tmp_path / input_name)]
    if manifest is not None:
        (tmp_path / "manifest.json").write_text(json.dumps(manifest), encoding="utf-8")
        argv += ["--manifest", str(tmp_path / "manifest.json")]
    report.unlink(missing_ok=True)
    status = cvf.main([*argv, *options])
    return status, json.loads(report.read_text(encoding="utf-8")) if report.is_file() else {}


def consequence_reason(fmt: str) -> str:
    """The red reason of one entry whose Consequence differs, as the format names the field."""
    return f"field {'consequence_terms' if fmt == 'json' else 'Consequence'}: 1 differing entries"


REFERENCE_MANIFEST = {"divergences": [fabricated_item(0, REMOVED_CLASS, **{WITH_REFERENCE: [KEPT_SET]})]}
REFERENCE_MASKS = ("--masks", REMOVED_CLASS)


@pytest.mark.parametrize("fmt", MANIFEST_FORMATS)
def test_a_run_without_a_reference_sequence_that_writes_the_sets_without_one_observes_the_item(tmp_path, fmt):
    """Crossing 1: under ``--reference-sequence absent`` an item that carries the
    with-reference key documents its ``vep_rs_consequence_sets``, and a candidate that wrote
    them is green with the item counted."""
    status, report = compare_fabricated(tmp_path, fmt, [KEPT_SET], [LOST_SET], REFERENCE_MANIFEST, *REFERENCE_MASKS, "--reference-sequence", "absent")
    assert status == 0 and report["verdict"] == "green", report.get("reasons")
    assert report["masks"]["applied"] == {REMOVED_CLASS: 1} and report["counts"]["documented_divergences_skipped"] == 1
    assert report["reference_sequence"] == "absent"


@pytest.mark.parametrize("fmt", MANIFEST_FORMATS)
def test_a_run_with_a_reference_sequence_that_writes_the_stated_sets_is_compared_exactly(tmp_path, fmt):
    """Crossing 2: under ``--reference-sequence present`` an item whose with-reference sets are
    Ensembl VEP's own documents nothing: the row is compared like any other, no difference is
    seen, and the item is neither skipped as documented nor reported as not observed."""
    status, report = compare_fabricated(tmp_path, fmt, [KEPT_SET], [KEPT_SET], REFERENCE_MANIFEST, *REFERENCE_MASKS, "--reference-sequence", "present")
    assert status == 0 and report["verdict"] == "green", report.get("reasons")
    assert report["stale_divergences"] == [] and report["counts"]["documented_divergences_skipped"] == 0
    assert report["counts"]["compared"] == (1 if fmt in ("default", "tab", "parquet") else 2)
    assert report["reference_sequence"] == "present"


@pytest.mark.parametrize("fmt", MANIFEST_FORMATS)
def test_a_run_without_a_reference_sequence_that_writes_the_with_reference_sets_is_red(tmp_path, fmt):
    """Crossing 3: a run without a reference sequence that wrote Ensembl VEP's set leaves the
    item not observed."""
    status, report = compare_fabricated(tmp_path, fmt, [KEPT_SET], [KEPT_SET], REFERENCE_MANIFEST, *REFERENCE_MASKS, "--reference-sequence", "absent")
    assert status == 1 and report["reasons"] == ["documented divergences not observed: 1"]


@pytest.mark.parametrize("fmt", MANIFEST_FORMATS)
def test_a_run_with_a_reference_sequence_that_writes_the_sets_without_one_is_red(tmp_path, fmt):
    """Crossing 4: a run with a reference sequence that wrote the sets of a run without one is
    a plain difference of the Consequence. The item's class is a built-in row class too, whose
    predicate admits the pair; it takes no row of a key the manifest states as equal."""
    status, report = compare_fabricated(tmp_path, fmt, [KEPT_SET], [LOST_SET], REFERENCE_MANIFEST, *REFERENCE_MASKS, "--reference-sequence", "present")
    assert status == 1 and consequence_reason(fmt) in report["reasons"], report["reasons"]
    assert report["masks"]["applied"] == {} and report["stale_divergences"] == []
    # The same pair with no item on the key is the class's own: the predicate admits it.
    status, report = compare_fabricated(tmp_path / "unstated", fmt, [KEPT_SET], [LOST_SET], {"divergences": []}, *REFERENCE_MASKS, "--reference-sequence", "present")
    assert status == 0 and report["masks"]["applied"] == {REMOVED_CLASS: 1}


@pytest.mark.parametrize("fmt", MANIFEST_FORMATS)
def test_an_item_without_the_key_and_a_call_without_the_setting_read_alike(tmp_path, fmt):
    """A call that states no setting reads an item's ``vep_rs_consequence_sets`` whether or not
    the item carries the with-reference key, and an item without the key reads the same under
    both settings: a candidate that wrote the documented set is green with the item counted,
    one that wrote Ensembl VEP's set leaves it not observed."""
    plain = {"divergences": [fabricated_item(0, REMOVED_CLASS)]}
    readings = [(REFERENCE_MANIFEST, ()), (plain, ())]
    for n, (manifest, setting) in enumerate(readings):
        status, report = compare_fabricated(tmp_path / f"observed{n}", fmt, [KEPT_SET], [LOST_SET], manifest, *REFERENCE_MASKS, *setting)
        assert status == 0 and report["masks"]["applied"] == {REMOVED_CLASS: 1}, (n, report.get("reasons"))
        status, report = compare_fabricated(tmp_path / f"unobserved{n}", fmt, [KEPT_SET], [KEPT_SET], manifest, *REFERENCE_MASKS, *setting)
        assert status == 1 and report["reasons"] == ["documented divergences not observed: 1"], (n, report.get("reasons"))
    for n, setting in enumerate(("present", "absent")):
        status, report = compare_fabricated(tmp_path / f"told{n}", fmt, [KEPT_SET], [LOST_SET], plain, *REFERENCE_MASKS, "--reference-sequence", setting)
        assert status == 0 and report["masks"]["applied"] == {REMOVED_CLASS: 1}, (setting, report.get("reasons"))
        status, report = compare_fabricated(tmp_path / f"told-unobserved{n}", fmt, [KEPT_SET], [KEPT_SET], plain, *REFERENCE_MASKS, "--reference-sequence", setting)
        assert status == 1 and report["reasons"] == ["documented divergences not observed: 1"], (setting, report.get("reasons"))


def test_an_item_stated_equal_with_a_reference_sequence_is_not_counted_as_applied(tmp_path):
    """The applied count of a class is the entries it sets aside. Of two items of one class,
    the one whose with-reference sets are Ensembl VEP's own sets nothing aside in a run with a
    reference sequence: the class is applied to one entry there and to two in a run without
    one, while both items stay available."""
    manifest = {"divergences": [fabricated_item(0, REMOVED_CLASS, **{WITH_REFERENCE: [KEPT_SET]}), fabricated_item(1, REMOVED_CLASS)]}
    counts = {}
    for setting, actual in (("present", [KEPT_SET, LOST_SET]), ("absent", [LOST_SET, LOST_SET]), (None, [LOST_SET, LOST_SET])):
        options = ("--reference-sequence", setting) if setting else ()
        for fmt in MANIFEST_FORMATS:
            status, report = compare_fabricated(tmp_path / f"{setting}-{fmt}", fmt, [KEPT_SET, KEPT_SET], actual, manifest, *REFERENCE_MASKS, *options)
            assert status == 0, (setting, fmt, report.get("reasons"))
            assert report["masks"]["available"] == {REMOVED_CLASS: 2} and report["masks"]["unused"] == []
            counts[setting, fmt] = report["masks"]["applied"][REMOVED_CLASS]
    assert counts == {(setting, fmt): (1 if setting == "present" else 2) for setting in ("present", "absent", None) for fmt in MANIFEST_FORMATS}


def test_an_item_documents_its_with_reference_sets_where_they_are_not_ensembl_veps(tmp_path):
    """With-reference sets other than Ensembl VEP's are the item's documented sets in a run
    with a reference sequence: the candidate is held to them, the item counted, and the sets
    of a run without one are then not observed."""
    manifest = {"divergences": [fabricated_item(0, "some_class", **{WITH_REFERENCE: [OTHER_SET]})]}
