def test_stop_codon_unshifted_span_is_asked_before_the_stop_codon_test_classes():
    """``stop_codon_unshifted_span`` stands before every class of the stop codon tests in
    ``TERM_PAIR_CLASSES``, so a row with a positive SHIFT_LENGTH that has its shape and one of
    theirs is its row, counted under it alone."""
    names = list(cvf.TERM_PAIR_CLASSES)
    assert cvf.TERM_PAIR_FOLLOWING_CLASSES
    assert all(names.index(cvf.STOP_CODON_UNSHIFTED_SPAN) < names.index(klass) for klass in cvf.TERM_PAIR_FOLLOWING_CLASSES)
    terms = "splice_region_variant,{},3_prime_UTR_variant"
    both = (*cvf.TERM_PAIR_FOLLOWING_CLASSES, cvf.STOP_CODON_UNSHIFTED_SPAN)
    shifted = "IMPACT=LOW;STRAND=-1;SHIFT_LENGTH=2"
    reference = stop_codon_text(terms.format("coding_sequence_variant"), "1705", "1630", shifted, location="3:36993663")
    candidate = stop_codon_text(terms.format("stop_retained_variant"), "1705", "1630", shifted, location="3:36993663")
    (e,), (a,) = cvf.parse_default(reference), cvf.parse_default(candidate)
    assert cvf.stop_codon_unshifted_span_pair(e, a) and cvf.stop_codon_overlap_genomic_span_pair(e, a)
    report, documented = compare_default(reference, candidate, *both)
    assert report["verdict"] == "green" and documented.applied == {cvf.STOP_CODON_UNSHIFTED_SPAN: 1}
    report, documented = compare_default(reference, candidate, cvf.STOP_CODON_OVERLAP_GENOMIC_SPAN)
    assert report["verdict"] == "green" and documented.applied == {cvf.STOP_CODON_OVERLAP_GENOMIC_SPAN: 1}


