    assert cvf.FIELD_CLASSES[klass] == cvf.TERM_PAIR_FOLLOWING_FIELDS

    def text(terms: str, impact: str, cdna: str = "7054-7055", cds: str = "6977-6978") -> str:
        extra = f"IMPACT={impact};STRAND=-1" if impact else "STRAND=-1"
        return stop_codon_text(terms, cdna, cds, extra, allele="N" * 4, location="19:13208046-13208047")

    reference, candidate = text("stop_gained,frameshift_variant", "HIGH"), text("inframe_insertion,stop_retained_variant", "MODERATE")
    report, documented = compare_default(reference, candidate, klass)
