    assert compare_default(reference, candidate)[0]["verdict"] == "red"
    elsewhere = text("stop_gained,frameshift_variant", "HIGH", "7054-7055", "?-6978"), text("inframe_insertion,stop_retained_variant", "MODERATE", "7054-7055", "?-6978")
    report, documented = compare_default(*elsewhere, klass)
    assert report["verdict"] == "red" and documented.applied == {}
