def test_front_end_hands_everything_over_where_the_conservation_rewrite_reaches_a_key(both_paths, tmp_path):
    """``conservation_short_name_spelling`` rewrites the whole reference text: a tab column
    line naming the misspelt key on both sides is renamed on the reference's side alone, and a
    misspelt key inside a reference Feature moves the row to another key. Neither shape shows
    in a row's own text, so every row is handed over."""
    header = "#Uploaded_variation\tLocation\tAllele\tFeature\tFeature_type\tConsequence\tphlyoP100way"
    rows = [f"rec{r}\t21:{1000 + r}\t{'ACGT'[r % 4]}\tENST1\tTranscript\tintron_variant\t0.{r}" for r in range(6)]
    expected, actual = tmp_path / "e.tab", tmp_path / "a.tab"
    expected.write_text("\n".join([header, *rows]) + "\n", encoding="utf-8")
    actual.write_text("\n".join([header, *rows]) + "\n", encoding="utf-8")
    options = ("--masks", "conservation_short_name_spelling")
    whole = f"[compare_vep_formats] every row was handed over by {both_paths.front_end}: a listed text stands in the reference's column line or a key column\n"
    _, out, code, err = both_paths.files(expected, actual, *options, fmt="tab")
    assert code == 1 and out == "tab: red\n  field phlyoP100way: 6 differing entries\n  field phyloP100way: 6 differing entries\n"
    assert err == whole
    _, out, code, err = both_paths.files(expected, actual, fmt="tab")
    assert (out, code) == ("tab: green\n", 0) and "6 of 6 reference rows were kept back" in err
    rows = planted_rows()
    keyed = [*rows[:4], default_row("rec2", "21:1002", "G", "phlyoP7way", "intron_variant", "IMPACT=MODIFIER"), *rows[4:]]
    spelt = [row.replace("phlyoP7way", "phyloP7way") for row in keyed]
    _, out, code, err = both_paths.rows(keyed, spelt, *options)
    assert (out, code, err) == ("default: green\n", 0, whole)
    _, out, code, err = both_paths.rows(keyed, keyed, *options)
    assert code == 1 and "missing in the candidate: 1 entries" in out and err == whole


def test_front_end_hands_everything_over_where_a_location_holds_a_space(both_paths):
    """A record's label is its Location, a space and its Uploaded_variation, so a Location
    holding a space can share a label with a row of another Location: the candidate-only row
    of ``frequency_filter_zero_value`` and of ``merged_same_stable_id_collapse`` is judged by
    the labels of the reference's rows, a row at another Location among them."""
    reference = [default_row("-", "21:5 x", "A", "ENST1", "intron_variant", "IMPACT=MODIFIER")]
    zero = default_row("x", "21:5", "A", "ENST2", "intron_variant", "IMPACT=MODIFIER;FREQS=pop:A:0")
    whole = f"[compare_vep_formats] every row was handed over by {both_paths.front_end}: a Location holds a space\n"
    _, out, code, err = both_paths.rows(reference, [*reference, zero], "--masks", "frequency_filter_zero_value")
    assert code == 1 and out == "default: red\n  unexpected in the candidate: 1 entries\n" and err == whole
    collapsed = default_row("x", "21:5", "A", "ENST2", "intron_variant", "IMPACT=MODIFIER;SOURCE=RefSeq")
    _, out, code, err = both_paths.rows(reference, [*reference, collapsed], "--masks", "merged_same_stable_id_collapse")
    assert (out, code, err) == ("default: green\n", 0, whole)


def test_literal_head_reads_only_a_head_every_match_starts_with():
    """The text handed to the front end must be in every reference line the class rewrites:
    a pattern with an alternation, a flag, no literal head or a quantifier on its head's
    last character gives none or a shorter one."""
    assert cvf.literal_head(re.compile(r"abc(\d+)x")) == "abc"
    assert cvf.literal_head(re.compile(r"abc?d")) == "ab"
    assert cvf.literal_head(re.compile(r"ab{2}")) == "a"
    assert cvf.literal_head(re.compile(r"abc|x")) is None
    assert cvf.literal_head(re.compile(r"(abc)")) is None
    assert cvf.literal_head(re.compile(r"abc", re.IGNORECASE)) is None
    assert cvf.literal_head(re.compile(r"a?")) is None


def test_front_end_takes_a_location_whose_rows_stand_apart_as_one_group(both_paths):
    """A Location that returns after two other records' rows is one group: written alike it
    is kept back with the rows between; a difference in its late row hands over the group
    and the rows between, and an order difference inside that span is found at its place
    among all shared keys."""
    rows = planted_rows()
    apart = [*rows[:10], planted_row(2, "ENST9"), *rows[10:]]
    report, out, code, err = both_paths.rows(apart, apart)
    assert (out, code) == ("default: green\n", 0) and "17 of 17 reference rows were kept back" in err
    late = [*rows[:10], planted_row(2, "ENST9", "IMPACT=LOW;STRAND=1;DOMAINS=db:a2,db:b2"), *rows[10:]]
    report, out, code, err = both_paths.rows(apart, late)
    assert code == 1 and "field IMPACT: 1 differing entries" in out
    assert "10 of 17 reference rows were kept back" in err and "3 of 8 record groups handed over" in err
    moved = [*rows[:6], rows[8], rows[9], rows[6], rows[7], planted_row(2, "ENST9", "IMPACT=LOW;STRAND=1;DOMAINS=db:a2,db:b2"), *rows[10:]]
    report, out, code, _ = both_paths.rows(apart, moved)
    assert code == 1 and "order differs at shared position 6" in out
    assert report["order"]["first_divergence"] == 6


def test_front_end_reads_note_lines_that_differ_and_hands_over_under_another_column_line(both_paths, tmp_path):
    """The two engines' ``##`` lines differ and no entry reads them: the rows are kept back.
    Under a column line that names a column differently no row's text settles its entry, and
    every row is handed over."""
    rows = planted_rows()
    expected, actual = tmp_path / "e.txt", tmp_path / "a.txt"
    expected.write_text("## reference engine\n## IMPACT : the reference's text\n" + default_text(*rows), encoding="utf-8")
    actual.write_text("## candidate engine\n" + default_text(*rows), encoding="utf-8")
    _, out, code, err = both_paths.files(expected, actual)
    assert (out, code) == ("default: green\n", 0) and "16 of 16 reference rows were kept back" in err
    actual.write_text(default_text(*rows).replace("\tGene\t", "\tGENE\t", 1), encoding="utf-8")
    _, out, code, err = both_paths.files(expected, actual)
    assert code == 1 and "field GENE: 16 differing entries" in out and "field Gene: 16 differing entries" in out
    assert err == f"[compare_vep_formats] every row was handed over by {both_paths.front_end}: the two outputs' column lines differ\n"


def test_front_end_counts_the_kept_back_rows_under_a_floor_in_the_tab_format(both_paths, tmp_path):
    """A tab comparison of gzipped outputs, one padded with zero bytes: a floor is read against
    the populated counts of every row, the kept-back ones included, on both sides."""
    header = "#Uploaded_variation\tLocation\tAllele\tFeature\tFeature_type\tConsequence\tIMPACT\tSYMBOL"
    rows = [f"rec{r}\t21:{1000 + r}\t{'ACGT'[r % 4]}\tENST{t}\tTranscript\tintron_variant\tMODIFIER\t{'-' if r % 2 else 'GENE'}"
            for r in range(8) for t in (1, 2)]
    candidate = [*rows[:5], rows[5].replace("MODIFIER", "LOW"), *rows[6:]]
    expected, actual = tmp_path / "e.tab.gz", tmp_path / "a.tab.gz"
    with gzip.open(expected, "wt", encoding="utf-8") as fh:
        fh.write("\n".join(["## reference", header, *rows]) + "\n")
    with gzip.open(actual, "wt", encoding="utf-8") as fh:
        fh.write("\n".join([header, *candidate]) + "\n")
    # Zero bytes after a gzip member are padding to both readers.
    with open(actual, "ab") as fh:
        fh.write(bytes(512))
    report, out, code, err = both_paths.files(expected, actual, "--floors", "SYMBOL=8,IMPACT=16", fmt="tab")
    assert code == 1 and out == "tab: red\n  field IMPACT: 1 differing entries\n"
    assert report["columns"]["SYMBOL"]["expected_populated"] == report["columns"]["SYMBOL"]["actual_populated"] == 8
    assert report["columns"]["SYMBOL"]["floor_met"] is True and "14 of 16 reference rows were kept back" in err
    report, out, code, _ = both_paths.files(expected, actual, "--floors", "SYMBOL=9", fmt="tab")
    assert "  floor SYMBOL=9: expected populated 8, actual populated 8\n" in out


def test_front_end_hands_over_a_row_whose_shift_length_the_interpreter_does_not_convert(both_paths):
    """A term-pair class reads the SHIFT_LENGTH of every Transcript row both sides write. A
    superscript digit, which ``str.isdigit`` takes and ``int`` does not read, and a number
    longer than ``int`` converts end the comparison of the whole outputs with the
    comparator's error; the front end hands a row over that holds a byte outside ASCII or
    a run of more than 640 digits, so the handed-over comparison ends with the same error.
    A SHIFT_LENGTH ``int`` reads is compared and its row kept back."""
    rows = planted_rows()
    for value, klass in (("\u00b2", "mature_mirna_unshifted_span"), ("7" * 5000, "stop_codon_unshifted_span")):
        shifted = [planted_row(0, "ENST1", f"IMPACT=MODIFIER;SHIFT_LENGTH={value}"), *rows[1:]]
        report, out, code, err = both_paths.rows(shifted, shifted, "--masks", klass)
        assert (report, out, code) == (None, "", 2)
        shown = value if len(value) <= 24 else value[:24] + "..."
        assert err == f"ERROR: [compare_vep_formats] SHIFT_LENGTH {shown!r} is not an integer\n"
    shifted = [planted_row(0, "ENST1", "IMPACT=MODIFIER;SHIFT_LENGTH=" + "7" * 640), *rows[1:]]
    _, out, code, err = both_paths.rows(shifted, shifted, "--masks", "stop_codon_unshifted_span")
    assert (out, code) == ("default: green\n", 0) and "16 of 16 reference rows were kept back" in err


def nested_object(depth: int) -> str:
    """The text of a JSON object nested ``depth`` deep."""
    return '{"a":' * depth + "1" + "}" * depth


def test_front_end_hands_over_a_row_whose_object_nests_past_the_interpreter_s_call_depth(both_paths):
    """A GA4GH_VRS object is put in canonical form on every row. One nested 1,000 deep ends
    the comparison of the whole outputs with the comparator's error; the front end hands a
    row over that holds more than 64 opening brackets, so the handed-over comparison ends
    with the same error. 60,000 opening brackets, which are no object, end both runs alike:
    with that error or compared as text, as the interpreter's JSON reader takes them. An
    object nested 64 deep is compared and its row kept back. Beside a candidate that cannot
    be read, the nested object ends both runs with exit 2 and no report."""
    rows = planted_rows()
    nested = [planted_row(0, "ENST1", f"GA4GH_VRS={nested_object(1000)}"), *rows[1:]]
    report, out, code, err = both_paths.rows(nested, nested)
    assert (report, out, code) == (None, "", 2)
    assert err == 'ERROR: [compare_vep_formats] a JSON object is nested too deep to read: {"a":{"a":{"a":{"a":{"a"...\n'
    # Beside a candidate that cannot be read, both runs end with the comparator's error.
    reference = both_paths.tmp_path / "nested.txt"
    reference.write_text(default_text(*nested), encoding="utf-8")
    report, out, code, _ = both_paths.files(reference, both_paths.tmp_path / "absent.txt")
    assert (report, out, code) == (None, "", 2)
    opened = [planted_row(0, "ENST1", "GA4GH_VRS=" + "[" * 60000), *rows[1:]]
    report, out, code, err = both_paths.rows(opened, opened)
    assert (report, out, code) == (None, "", 2) or (out, code) == ("default: green\n", 0)
    shallow = [planted_row(0, "ENST1", f"GA4GH_VRS={nested_object(64)}"), *rows[1:]]
    _, out, code, err = both_paths.rows(shallow, shallow)
    assert (out, code) == ("default: green\n", 0) and "16 of 16 reference rows were kept back" in err
    shallow[0] = planted_row(0, "ENST1", f"GA4GH_VRS={nested_object(65)}")
    _, out, code, err = both_paths.rows(shallow, shallow)
    assert (out, code) == ("default: green\n", 0) and "14 of 16 reference rows were kept back" in err


def gzip_member(text: bytes, flags: int = 0, fields: bytes = b"", stream: bytes | None = None) -> bytes:
    """One gzip member holding ``text`` under a header of ``flags``, ``fields`` standing
    between the fixed header and the deflate stream, which is ``stream`` or the one zlib
    writes for the text."""
    if stream is None:
        deflater = zlib.compressobj(9, zlib.DEFLATED, -zlib.MAX_WBITS)
        stream = deflater.compress(text) + deflater.flush()
    return b"\x1f\x8b\x08" + bytes([flags]) + b"\0\0\0\0\0\xff" + fields + stream + struct.pack("<II", zlib.crc32(text), len(text))


def deflate_with_a_copy(before: bytes, after: bytes) -> bytes:
    """One final deflate block of the fixed codes (RFC 1951, 3.2.6) that writes ``before``,
    copies three bytes from five bytes back and writes ``after``."""
    bits = [1, 1, 0]

    def code(value: int, width: int) -> None:
        bits.extend((value >> (width - 1 - i)) & 1 for i in range(width))

    def literals(text: bytes) -> None:
        for byte in text:
            assert byte < 144, "a literal of the eight-bit codes"
            code(0x30 + byte, 8)

    literals(before)
    code(1, 7)
    code(4, 5)
    bits.append(0)
    literals(after)
    code(0, 7)
    return bytes(sum(bit << k for k, bit in enumerate(bits[i : i + 8])) for i in range(0, len(bits), 8))


def test_front_end_reads_a_gzip_header_as_the_comparator_reads_it(both_paths):
    """``gzip.open`` reads past a member's header checksum without a check and past the flag
    bits the format reserves, and takes an extra field, a file name and a comment: outputs
    gzipped under such headers are compared through the front end as on the whole outputs."""
    rows = planted_rows()
    other = [*rows[:6], planted_row(3, "ENST1", "IMPACT=LOW;STRAND=1;DOMAINS=db:a3,db:b3"), *rows[7:]]
    reference = both_paths.tmp_path / "expected.txt.gz"
    candidate = both_paths.tmp_path / "actual.txt.gz"
    reference.write_bytes(gzip_member(default_text(*rows).encode(), 0xE2, b"\xff\xff"))
    for flags, fields in ((0x02, b"\x12\x34"), (0x20, b""), (0x1E, b"\x02\x00xyname\0note\0\0\0")):
        candidate.write_bytes(gzip_member(default_text(*other).encode(), flags, fields))
        _, out, code, err = both_paths.files(reference, candidate)
        assert code == 1 and out == "default: red\n  field Extra: 1 differing entries\n  field IMPACT: 1 differing entries\n"
        assert "14 of 16 reference rows were kept back" in err


def test_front_end_refuses_a_deflate_stream_that_zlib_refuses(both_paths):
    """A gzip member whose deflate stream copies from before its start is refused by zlib,
    and the comparison of the whole outputs ends in the comparator's error. The front end
    refuses it as well, under the checksum and length of the text a decoder that takes the
    copy writes (a zero byte for each place before the start): both runs exit 2 and write
    no report."""
    rows = planted_rows()
    text = default_text(*rows).encode()
    taken = text[:3] + b"\0\0" + text[:1] + text[3:]
    reference = both_paths.tmp_path / "expected.txt"
    candidate = both_paths.tmp_path / "actual.txt.gz"
    reference.write_bytes(text)
    candidate.write_bytes(gzip_member(taken, stream=deflate_with_a_copy(text[:3], text[3:])))
    report, out, code, err = both_paths.files(reference, candidate)
    assert (report, out, code) == (None, "", 2)
    assert err.count("\n") == 1 and err.startswith(f"ERROR: [compare_vep_formats] {both_paths.front_end} exited 1: ")
    # The same stream with the copy inside the text is read by both.
    candidate.write_bytes(gzip_member(text[:5] + text[:3] + text[5:], stream=deflate_with_a_copy(text[:5], text[5:])))
    _, out, code, _ = both_paths.files(reference, candidate)
    assert code == 1 and out.startswith("default: red\n")


def test_front_end_reads_an_output_whose_path_is_spelt_as_its_help_option(both_paths):
    """An output whose path is spelt ``-h`` or ``--help`` reaches the front end as the value
    of ``--expected`` or ``--actual``, never as its help option, and is compared through it
    as on the whole outputs."""
    rows = planted_rows()
    other = [*rows[:6], planted_row(3, "ENST1", "IMPACT=LOW;STRAND=1;DOMAINS=db:a3,db:b3"), *rows[7:]]
    both_paths.monkeypatch.chdir(both_paths.tmp_path)
    Path("-h").write_text(default_text(*rows), encoding="utf-8")
    Path("--help").write_text(default_text(*other), encoding="utf-8")
    seen = []
    for name, switch in (("whole", ""), ("handed", both_paths.front_end)):
        both_paths.monkeypatch.setenv(cvf.FRONT_END_VARIABLE, switch)
        code = cvf.main(["--format", "default", "--expected=-h", "--actual=--help", "--report", f"{name}.json"])
        seen.append((Path(f"{name}.json").read_bytes(), both_paths.capsys.readouterr().out, code))
    assert seen[1] == seen[0]
    assert seen[0][1:] == ("default: red\n  field Extra: 1 differing entries\n  field IMPACT: 1 differing entries\n", 1)


def test_front_end_leaves_the_comparisons_outside_it_on_the_whole_outputs(both_paths, tmp_path):
    """A structural-variant class, ``individual_allele_order``, ``--keep-only`` and a format
    other than default and tab are compared on the whole outputs with the variable set, and
    the line on the standard error names what is outside the front end."""
    rows = planted_rows()
    outside = "[compare_vep_formats] the whole outputs were compared: {} is outside the front end\n"
    for klass in (*cvf.STRUCTURAL_VARIANT_CLASSES, cvf.INDIVIDUAL_ALLELE_ORDER):
        if klass in cvf.CACHE_READING_CLASSES:
            continue
        _, out, code, err = both_paths.rows(rows, rows, "--masks", klass, "--input", str(CORPUS / "variants.vcf"))
        assert (out, code, err) == ("default: green\n", 0, outside.format(klass))
    regulatory = default_row("rec2", "21:1002", "G", "ENSR1", "regulatory_region_variant", "IMPACT=MODIFIER", feature_type="RegulatoryFeature")
    _, out, code, err = both_paths.rows([*rows, regulatory], [*rows, regulatory], "--keep-only", "regulatory_feature_rows")
    assert (out, code, err) == ("default: green\n", 0, outside.format("--keep-only"))
    vcf = EXPECTED / "vcf.vcf.gz"
    _, out, code, err = both_paths.files(vcf, vcf, "--input", str(CORPUS / "variants.vcf"), fmt="vcf")
    assert (out, code, err) == ("vcf: green\n", 0, outside.format("the vcf format"))
    both_paths.monkeypatch.setenv(cvf.FRONT_END_VARIABLE, both_paths.front_end)
    warnings = tmp_path / "warnings.txt"
    warnings.write_text("", encoding="utf-8")
    assert cvf.main(["--warnings", "--expected", str(warnings), "--actual", str(warnings)]) == 0
    assert both_paths.capsys.readouterr().err == "[compare_vep_formats] the whole outputs were compared: only a default or tab comparison is handed over\n"


def test_front_end_switch_that_names_no_executable_or_fails_is_an_error(both_paths, tmp_path, monkeypatch, capsys):
    """A value naming no executable ends every mode with one error line and exit 2, never a
    comparison of the whole outputs; so does a front end that exits non-zero, with its last
    line; an empty value compares the whole outputs and writes nothing on the standard
    error."""
    rows = planted_rows()
    expected = tmp_path / "expected.txt"
    expected.write_text(default_text(*rows), encoding="utf-8")
    args = ["--format", "default", "--expected", str(expected), "--actual", str(expected), "--report", str(tmp_path / "r.json")]
    monkeypatch.setenv(cvf.FRONT_END_VARIABLE, str(tmp_path / "absent"))
    assert cvf.main(args) == 2
    assert capsys.readouterr().err == f"ERROR: [compare_vep_formats] VEP_FORMATS_REMAINDER={tmp_path / 'absent'} names no executable\n"
    assert cvf.main(["--warnings", "--expected", str(expected), "--actual", str(expected)]) == 2
    capsys.readouterr()
    assert not (tmp_path / "r.json").exists()
    failing = tmp_path / "failing"
    failing.write_text("#!/bin/sh\necho first line >&2\necho 'ERROR: [stub] refused' >&2\nexit 3\n", encoding="utf-8")
    failing.chmod(0o755)
    monkeypatch.setenv(cvf.FRONT_END_VARIABLE, str(failing))
    assert cvf.main(args) == 2
    captured = capsys.readouterr()
    assert (captured.out, captured.err) == ("", f"ERROR: [compare_vep_formats] {failing} exited 3: ERROR: [stub] refused\n")
    undecodable = tmp_path / "undecodable.txt"
    undecodable.write_bytes(default_text(*rows).encode() + b"rec\t21:1\t\xff\n")
    monkeypatch.setenv(cvf.FRONT_END_VARIABLE, both_paths.front_end)
    assert cvf.main([*args[:5], str(undecodable), *args[6:]]) == 2
    captured = capsys.readouterr()
    assert captured.out == "" and captured.err.count("\n") == 1 and "the text is not UTF-8" in captured.err

    def no_room(*args, **kwargs):
        raise OSError(28, "No space left on device")

    with monkeypatch.context() as patch:
        patch.setattr(cvf.tempfile, "TemporaryDirectory", no_room)
        assert cvf.main(args) == 2
    captured = capsys.readouterr()
    assert (captured.out, captured.err) == ("", "ERROR: [compare_vep_formats] cannot make the front end's directory: No space left on device\n")
    monkeypatch.setenv(cvf.FRONT_END_VARIABLE, "")
    assert cvf.main(args) == 0
    assert capsys.readouterr() == ("default: green\n", "")
    assert cvf.FRONT_END_VARIABLE in cvf.build_parser().format_help()


def test_front_end_and_the_whole_outputs_agree_on_random_pairs(both_paths):
    """Three hundred seeded pairs of outputs, each the reference's rows with rows changed,
    dropped, added, repeated, exchanged within a record and across records, a Location
    returning later and a list in another order, compared with and without ``order_only``
    and ``--unordered``: both paths write the same report, standard output and exit code."""
    import random

    rng = random.Random(7919)
    verdicts = Counter()
    for _ in range(300):
        records = rng.randrange(3, 14)
        reference: list[str] = []
        for r in range(records):
            location = f"21:{1000 + (rng.randrange(r + 1) if rng.random() < 0.15 else r)}"
            for t in range(rng.randrange(1, 4)):
                reference.append(planted_row(r, f"ENST{t}", location=location))
        candidate = list(reference)
        for _ in range(rng.randrange(0, 5)):
            at = rng.randrange(len(candidate))
            edit = rng.randrange(8)
            if edit == 0:
                candidate[at] = candidate[at].replace("IMPACT=MODIFIER", "IMPACT=LOW")
            elif edit == 1 and len(candidate) > 1:
                del candidate[at]
            elif edit == 2:
                candidate.insert(at, planted_row(rng.randrange(20), f"ENST{rng.randrange(5)}"))
            elif edit == 3:
                candidate.insert(at, candidate[at])
            elif edit == 4 and at + 1 < len(candidate):
                candidate[at], candidate[at + 1] = candidate[at + 1], candidate[at]
            elif edit == 5:
                other = rng.randrange(len(candidate))
                candidate[at], candidate[other] = candidate[other], candidate[at]
            elif edit == 6:
                candidate[at] = re.sub(r"DOMAINS=(db:a\d+),(db:b\d+)", r"DOMAINS=\2,\1", candidate[at])
            else:
                block = candidate[at : at + rng.randrange(1, 4)]
                del candidate[at : at + len(block)]
                to = rng.randrange(len(candidate) + 1)
                candidate[to:to] = block
        options = [*(("--masks", "order_only") if rng.random() < 0.5 else ()), *(("--unordered",) if rng.random() < 0.3 else ())]
        _, out, _, _ = both_paths.rows(reference, candidate, *options)
        verdicts[out.split("\n", 1)[0]] += 1
    assert verdicts["default: green"] > 30 and verdicts["default: red"] > 150, verdicts
